"""Permutation group of the 60 Gaussian-E8 lines generated by the 60 complex reflections s_r s_{Jr}; orbits on the 1500 3-flats."""
import sys, pickle
sys.path.insert(0, sys.path[0])
import numpy as np
from lines import views, e8_roots

def line_index(S):
    J = S.ops[1]; idx = {}
    for T, r in enumerate(S.reps):
        for v in (r, -r, J @ r, -(J @ r)): idx[tuple(v)] = T
    return idx

def generators(S):
    J = S.ops[1]; idx = line_index(S); gens = []
    for r in S.reps:
        out = []
        for T in range(S.v):
            x = S.reps[T]
            for a in (r, J @ r):            # real reflections in r and Jr (norm 8): x -> x - 2<x,a>/8 a
                x = x - (2 * int(x @ a) // 8) * a
            out.append(idx[tuple(x)])
        assert sorted(out) == list(range(S.v))
        gens.append(tuple(out))
    return gens

def closure(gens, n):
    G = {tuple(range(n))}; frontier = list(G)
    while frontier:
        new = []
        for p in frontier:
            for g in gens:
                q = tuple(g[p[i]] for i in range(n))
                if q not in G: G.add(q); new.append(q)
        frontier = new
    return G

if __name__ == '__main__':
    S = views()['Gauss']
    gens = generators(S)
    # check: generators preserve non-orthogonality
    for g in gens:
        P = np.array(g); assert (S.NO[np.ix_(P, P)] == S.NO).all()
    G = closure(gens, S.v); print('group order on lines', len(G))
    F = pickle.load(open('flats_Gauss.pkl', 'rb'))
    hyp = sorted(sorted(f) for f, d in F.items() if d == 3)
    hs = {frozenset(h) for h in hyp}; seen = set(); reps = []
    for h in hyp:
        if frozenset(h) in seen: continue
        orb = {frozenset(g[i] for i in h) for g in G}
        assert orb <= hs
        seen |= orb; reps.append((h, len(orb)))
    print('orbits on 3-flats:', [(len(h), n) for h, n in reps], 'total', sum(n for _, n in reps))
    pickle.dump({'G': sorted(G), 'hyp_reps': reps}, open('orbits.pkl', 'wb'))
